// TIM3a (RUN 4): builds data/timbres.bundle.json from the timbre files (user answer T4 — one file per timbre in the repo is the source of
// truth; the app loads ONE generated bundle). Order = data/timbres/index.json `order` (the menu order = the TIM1 registry order).
// Every record passes core/timbre.js checkTimbre first (a refused file stops the build, named).
// Usage: node tools/timbre-bundle.mjs          → writes the bundle
//        node tools/timbre-bundle.mjs --check  → exit 0 only if the bundle on disk equals what the files give (the data runner's row)
import { readFile, writeFile } from 'node:fs/promises';
const ROOT=new URL('../', import.meta.url), DIR=new URL('data/timbres/', ROOT), OUT=new URL('data/timbres.bundle.json', ROOT);
const T=await import(new URL('src/core/timbre.js', ROOT).href);

export async function buildBundle(){
  const idx=JSON.parse(await readFile(new URL('index.json', DIR), 'utf8'));
  const problems=[], records=[];
  if(!Array.isArray(idx.order) || new Set(idx.order).size!==idx.order.length) problems.push('index.json: `order` must list each id once');
  for(const id of idx.order||[]){
    let rec; try{ rec=JSON.parse(await readFile(new URL(id+'.json', DIR), 'utf8')); }catch(e){ problems.push(`${id}.json: ${e.message}`); continue; }
    const why=T.checkTimbre(rec); if(why){ problems.push(`${id}.json: ${why}`); continue; }
    if(rec.id!==id) problems.push(`${id}.json: its id is ${rec.id}`);
    records.push(rec);
  }
  const text=JSON.stringify({ format:T.BUNDLE_FORMAT, version:T.BUNDLE_VERSION, note:'GENERATED by tools/timbre-bundle.mjs from data/timbres/*.json — never edit by hand', records }, null, 1)+'\n';
  return { text, problems, n:records.length };
}
if(process.argv[1] && /timbre-bundle\.mjs$/.test(process.argv[1])){
  const b=await buildBundle();
  if(b.problems.length){ for(const p of b.problems) console.log('  ✗ '+p); console.log('[timbre-bundle] NOT A PASS — '+b.problems.length+' problem(s)'); process.exit(1); }
  if(process.argv.includes('--check')){
    let disk=''; try{ disk=await readFile(OUT, 'utf8'); }catch(e){}
    const same=disk.replace(/\r\n/g,'\n')===b.text;
    console.log(same ? `[timbre-bundle] PASS — the bundle equals the ${b.n} files` : '[timbre-bundle] NOT A PASS — data/timbres.bundle.json is stale: run node tools/timbre-bundle.mjs');
    process.exit(same?0:1);
  }
  await writeFile(OUT, b.text); console.log(`[timbre-bundle] wrote data/timbres.bundle.json — ${b.n} records`);
}
